#!/usr/bin/env python3
"""
ext_scanner.py - Browser-like page scanner using Selenium

Usage:
  python3 ext_scanner.py --url https://example.local --out report.json [--active]

Notes:
- Passive by default. --active enables safe non-executing marker injection (lab-only).
- Only target sites you own or have permission to test.
"""
import argparse, json, time, uuid
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.firefox.options import Options as FxOptions

# ---------- Config ----------
WAIT_SECONDS = 1.0
# ----------------------------

def collect_passive(driver, url):
    """Run JS in page to collect headers and DOM info (passive)."""
    info = {"url": url, "timestamp": time.time(), "csp": None, "meta": [], "scripts": [], "forms": [], "inline_scripts": 0}
    # read document properties
    js = """
    (function(){
      try {
        let out = {};
        out.title = document.title;
        out.location = location.href;
        out.meta = Array.from(document.getElementsByTagName('meta')).map(m => ({name: m.name || m.getAttribute('property'), content: m.content}));
        out.scripts = Array.from(document.getElementsByTagName('script')).map(s => ({src: s.src||null, inline: !!(s.src==''||!s.src)}));
        out.forms = Array.from(document.getElementsByTagName('form')).map(f => ({action: f.getAttribute('action'), method: (f.getAttribute('method')||'GET').toUpperCase(), inputs: Array.from(f.querySelectorAll('input,textarea,select')).map(i=>({name:i.name||null,type:i.type||i.tagName}))}));
        out.csp = null;
        // try reading meta CSP if present
        const meta = Array.from(document.querySelectorAll('meta[http-equiv]')).find(m=>/content-security-policy/i.test(m.httpEquiv));
        if (meta) out.csp = meta.content;
        return out;
      } catch(e) { return {error: String(e)}; }
    })();
    """
    result = driver.execute_script(js)
    info.update(result if isinstance(result, dict) else {})
    # count inline scripts
    info["inline_scripts"] = sum(1 for s in (info.get("scripts") or []) if s.get("inline"))
    return info

def safe_active_test_reflection(driver, marker):
    """
    Safe active check: place plain-text marker in each text input, submit if appropriate, then search for marker in page DOM.
    Marker is plain text (no tags) to avoid code execution.
    """
    findings = []
    inputs = driver.find_elements(By.CSS_SELECTOR, "input[type='text'], input:not([type]), textarea")
    for i, el in enumerate(inputs):
        try:
            el.clear()
            el.send_keys(marker)
            # attempt simple submit if inside a form with submit button present (we avoid submitting if form has action external)
            form = el.find_element(By.XPATH, "ancestor::form")
            action = form.get_attribute("action") or ""
            # only submit if action is empty or local
            if action.strip()=="" or action.startswith("/") or action.startswith(driver.current_url.split("/",3)[0]):
                # try pressing submit button if present
                try:
                    btn = form.find_element(By.CSS_SELECTOR, "input[type=submit], button[type=submit]")
                    btn.click()
                    time.sleep(WAIT_SECONDS)
                except Exception:
                    # fallback: don't submit; just check reflection on page
                    pass
            # scan DOM text for marker
            body_text = driver.execute_script("return document.body.innerText || ''")
            if marker in body_text:
                findings.append({"type":"reflected_text", "input_index": i, "note":"marker found in DOM text"})
        except Exception as e:
            # skip failures
            pass
    return findings

def main():
    p = argparse.ArgumentParser()
    p.add_argument("--url", required=True)
    p.add_argument("--out", default="ext_report.json")
    p.add_argument("--active", action="store_true", help="Enable safe active check (lab-only)")
    args = p.parse_args()

    opts = FxOptions()
    opts.headless = True
    driver = webdriver.Firefox(options=opts)  # change to Chrome if preferred and driver present
    try:
        print("[+] Opening", args.url)
        driver.set_page_load_timeout(20)
        driver.get(args.url)
        time.sleep(WAIT_SECONDS)
        report = {"passive": collect_passive(driver, args.url), "active_findings": []}
        if args.active:
            print("[!] Active safe testing enabled — only run in lab/with permission")
            marker = "TEST_MARKER_" + uuid.uuid4().hex[:8]  # plain-text marker
            report["active_findings"] = safe_active_test_reflection(driver, marker)
        # also grab response headers using fetch (same-origin) if available
        try:
            headers = driver.execute_script("""
              return fetch(location.href, {method:'HEAD'}).then(r => r.headers ? Array.from(r.headers.entries()) : []).catch(e=>[['fetch_error', String(e)]]);
            """)
            report["response_headers"] = dict(headers) if isinstance(headers, list) else headers
        except Exception:
            report["response_headers"] = None

        with open(args.out, "w") as f:
            json.dump(report, f, indent=2)
        print("[+] Report written to", args.out)
    finally:
        driver.quit()

if __name__ == "__main__":
    main()

/*
ext_scanner_c.c - Passive page scanner using libcurl + Gumbo
Compile:
  gcc -o ext_scanner_c ext_scanner_c.c -lcurl -lgumbo

Usage:
  ./ext_scanner_c https://example.local > report.txt
Notes:
  - Passive scanner: only issues HTTP(S) GET requests and parses the HTML.
  - This tool detects: missing CSP meta, inline scripts, external script sources, forms with method GET, and mixed-content resources.
*/
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <gumbo.h>

struct mem {
    char *buf; size_t size;
};
static size_t write_cb(void *ptr, size_t size, size_t nmemb, void *userdata) {
    size_t realsz = size * nmemb;
    struct mem *m = (struct mem*)userdata;
    char *n = realloc(m->buf, m->size + realsz + 1);
    if (!n) return 0;
    m->buf = n;
    memcpy(m->buf + m->size, ptr, realsz);
    m->size += realsz;
    m->buf[m->size] = 0;
    return realsz;
}

void traverse(GumboNode* node, const char* base_url, int* inline_scripts, int* external_scripts, int* forms_get, int* mixed_content) {
    if (node->type != GUMBO_NODE_ELEMENT) return;
    GumboAttribute* attr;
    GumboVector* children;
    switch (node->v.element.tag) {
        case GUMBO_TAG_SCRIPT:
            attr = gumbo_get_attribute(&node->v.element.attributes, "src");
            if (attr) (*external_scripts)++;
            else (*inline_scripts)++;
            break;
        case GUMBO_TAG_META:
            attr = gumbo_get_attribute(&node->v.element.attributes, "http-equiv");
            if (attr && strcasecmp(attr->value, "Content-Security-Policy")==0) {
                // presence indicates CSP meta tag
            }
            break;
        case GUMBO_TAG_LINK:
        case GUMBO_TAG_IMG:
        case GUMBO_TAG_SCRIPT:
        case GUMBO_TAG_IFRAME:
        {
            // check src/href attribute for mixed content (http resource on https base)
            GumboAttribute* src = gumbo_get_attribute(&node->v.element.attributes, "src");
            GumboAttribute* href = gumbo_get_attribute(&node->v.element.attributes, "href");
            const char* val = src ? src->value : (href ? href->value : NULL);
            if (val && base_url && strncasecmp(base_url, "https://", 8)==0 && strncasecmp(val, "http://", 7)==0) {
                (*mixed_content)++;
            }
            break;
        }
        case GUMBO_TAG_FORM:
        {
            attr = gumbo_get_attribute(&node->v.element.attributes, "method");
            if (attr) {
                if (strcasecmp(attr->value, "get")==0) (*forms_get)++;
            } else {
                // default is GET
                (*forms_get)++;
            }
            break;
        }
        default:
            break;
    }
    children = &node->v.element.children;
    for (unsigned int i=0;i<children->length;i++) traverse((GumboNode*)children->data[i], base_url, inline_scripts, external_scripts, forms_get, mixed_content);
}

int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr,"Usage: %s <url>\n", argv[0]); return 1; }
    const char* url = argv[1];
    CURL *curl = curl_easy_init();
    struct mem m = {NULL,0};
    if (!curl) return 1;
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &m);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, "ext-scanner/1.0");
    CURLcode rc = curl_easy_perform(curl);
    if (rc != CURLE_OK) {
        fprintf(stderr,"curl failed: %s\n", curl_easy_strerror(rc));
        curl_easy_cleanup(curl);
        free(m.buf);
        return 2;
    }
    char *content_type = NULL;
    curl_easy_getinfo(curl, CURLINFO_CONTENT_TYPE, &content_type);
    long response_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    double total_time = 0; curl_easy_getinfo(curl, CURLINFO_TOTAL_TIME, &total_time);

    printf("URL: %s\nHTTP Status: %ld\nContent-Type: %s\nSize: %zu bytes\n\n", url, response_code, content_type?content_type:"-", m.size);

    // parse with gumbo
    GumboOutput* output = gumbo_parse_with_options(&kGumboDefaultOptions, m.buf, m.size);
    int inline_scripts = 0, external_scripts = 0, forms_get = 0, mixed_content = 0;
    traverse(output->root, url, &inline_scripts, &external_scripts, &forms_get, &mixed_content);

    // check CSP meta presence
    GumboVector* head_children = &output->root->v.element.children;
    int csp_meta_found = 0;
    // simple scan for meta http-equiv
    // (we did not record earlier; re-scan meta tags quickly)
    // ... to keep code concise we will do a shallow search:
    GumboVector* html_children = &output->root->v.element.children;
    // This is approximate; for robust implementation find <meta http-equiv=Content-Security-Policy> precisely.
    const char *body_text = m.buf;
    if (strstr(body_text, "Content-Security-Policy") != NULL) csp_meta_found = 1;

    printf("Inline scripts: %d\nExternal scripts: %d\nForms with GET/default: %d\nMixed-content resources: %d\nCSP meta present (heuristic): %d\n", inline_scripts, external_scripts, forms_get, mixed_content, csp_meta_found);

    gumbo_destroy_output(&kGumboDefaultOptions, output);
    curl_easy_cleanup(curl);
    free(m.buf);
    return 0;
}
