const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const redis = require('redis');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
    origin: process.env.CORS_ORIGINS || ['http://localhost:3000'],
    credentials: true
}));
app.use(express.json());

// Redis client for token blacklisting
const redisClient = redis.createClient({
    url: process.env.REDIS_URL || 'redis://localhost:6379'
});
redisClient.connect();

// Rate limiting
const authLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 5, // 5 attempts per window
    message: 'Too many authentication attempts, please try again later.'
});

const apiLimiter = rateLimit({
    windowMs: 1 * 60 * 1000, // 1 minute
    max: 100 // 100 requests per minute
});

// JWT configuration
const JWT_CONFIG = {
    accessToken: {
        expiresIn: '15m',
        secret: process.env.JWT_ACCESS_SECRET || 'access-secret'
    },
    refreshToken: {
        expiresIn: '7d',
        secret: process.env.JWT_REFRESH_SECRET || 'refresh-secret'
    }
};

class JWTManager {
    static generateAccessToken(payload) {
        return jwt.sign(
            { 
                ...payload, 
                type: 'access',
                jti: this.generateTokenId() 
            },
            JWT_CONFIG.accessToken.secret,
            { expiresIn: JWT_CONFIG.accessToken.expiresIn }
        );
    }

    static generateRefreshToken(payload) {
        return jwt.sign(
            { 
                ...payload, 
                type: 'refresh',
                jti: this.generateTokenId() 
            },
            JWT_CONFIG.refreshToken.secret,
            { expiresIn: JWT_CONFIG.refreshToken.expiresIn }
        );
    }

    static generateTokenId() {
        return require('crypto').randomBytes(16).toString('hex');
    }

    static async verifyAccessToken(token) {
        try {
            // Check blacklist
            if (await redisClient.get(`blacklist:${token}`)) {
                throw new Error('Token revoked');
            }

            return jwt.verify(token, JWT_CONFIG.accessToken.secret);
        } catch (error) {
            throw new Error('Invalid token');
        }
    }

    static async verifyRefreshToken(token) {
        try {
            // Check blacklist
            if (await redisClient.get(`blacklist:${token}`)) {
                throw new Error('Token revoked');
            }

            return jwt.verify(token, JWT_CONFIG.refreshToken.secret);
        } catch (error) {
            throw new Error('Invalid refresh token');
        }
    }

    static async revokeToken(token, expiresIn) {
        await redisClient.setEx(
            `blacklist:${token}`,
            Math.floor(expiresIn / 1000), // Convert to seconds
            'revoked'
        );
    }
}

// Authentication middleware
const authenticateToken = async (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
        return res.status(401).json({ error: 'Access token required' });
    }

    try {
        const payload = await JWTManager.verifyAccessToken(token);
        req.user = payload;
        next();
    } catch (error) {
        return res.status(403).json({ error: 'Invalid or expired token' });
    }
};

// Routes
app.post('/auth/login', authLimiter, async (req, res) => {
    const { username, password } = req.body;

    // Validate input
    if (!username || !password) {
        return res.status(400).json({ error: 'Username and password required' });
    }

    // In production, get user from database
    const user = { id: 1, username: 'test', password: '$2a$12$hashedpassword' };

    // Verify password
    const validPassword = await bcrypt.compare(password, user.password);
    if (!validPassword) {
        return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate tokens
    const accessToken = JWTManager.generateAccessToken({ userId: user.id, username: user.username });
    const refreshToken = JWTManager.generateRefreshToken({ userId: user.id });

    res.json({
        access_token: accessToken,
        refresh_token: refreshToken,
        token_type: 'bearer',
        expires_in: 15 * 60 // 15 minutes in seconds
    });
});

app.post('/auth/refresh', async (req, res) => {
    const { refresh_token } = req.body;

    if (!refresh_token) {
        return res.status(400).json({ error: 'Refresh token required' });
    }

    try {
        const payload = await JWTManager.verifyRefreshToken(refresh_token);

        // Revoke old refresh token
        const decoded = jwt.decode(refresh_token);
        await JWTManager.revokeToken(refresh_token, decoded.exp * 1000 - Date.now());

        // Generate new tokens
        const accessToken = JWTManager.generateAccessToken({ userId: payload.userId, username: payload.username });
        const newRefreshToken = JWTManager.generateRefreshToken({ userId: payload.userId });

        res.json({
            access_token: accessToken,
            refresh_token: newRefreshToken,
            token_type: 'bearer',
            expires_in: 15 * 60
        });
    } catch (error) {
        return res.status(403).json({ error: 'Invalid refresh token' });
    }
});

app.post('/auth/logout', authenticateToken, async (req, res) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (token) {
        const decoded = jwt.decode(token);
        await JWTManager.revokeToken(token, decoded.exp * 1000 - Date.now());
    }

    res.json({ message: 'Successfully logged out' });
});

app.get('/protected', authenticateToken, apiLimiter, (req, res) => {
    res.json({ 
        message: 'This is a protected route',
        user: req.user 
    });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Secure API server running on port ${PORT}`);
});

from datetime import timedelta
from fastapi import FastAPI, Depends, HTTPException, status, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.security import OAuth2PasswordRequestForm
from slowapi import Limiter, _rate_limit_exceeded_handler
from slowapi.util import get_remote_address
from slowapi.errors import RateLimitExceeded
from slowapi.middleware import SlowAPIMiddleware
import uvicorn

from app.core.config import settings
from app.auth.jwt import jwt_manager, get_current_active_user, RateLimiter, IPBlocker
from app.auth.oauth import oauth_manager
from app.models.users import (
    UserCreate, UserInDB, Token, RefreshTokenRequest, 
    PasswordChangeRequest
)
from app.core.security import SecurityUtils

# Rate limiter
limiter = Limiter(key_func=get_remote_address)

app = FastAPI(
    title=settings.APP_NAME,
    debug=settings.DEBUG
)

# Middleware
app.add_middleware(
    CORSMiddleware,
    allow_origins=settings.CORS_ORIGINS,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

app.add_middleware(SlowAPIMiddleware)
app.state.limiter = limiter
app.add_exception_handler(RateLimitExceeded, _rate_limit_exceeded_handler)

# In-memory user store (replace with database in production)
users_db = {}

@app.post("/auth/register", response_model=Token)
@limiter.limit("5 per minute")
async def register(
    request: Request,
    user_data: UserCreate
):
    """User registration endpoint"""
    # Check if user already exists
    if user_data.email in users_db or user_data.username in [u.username for u in users_db.values()]:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="User already exists"
        )

    # Create user
    user_id = len(users_db) + 1
    hashed_password = SecurityUtils.hash_password(user_data.password)

    user = UserInDB(
        id=user_id,
        email=user_data.email,
        username=user_data.username,
        full_name=user_data.full_name,
        hashed_password=hashed_password,
        created_at=datetime.utcnow(),
        updated_at=datetime.utcnow()
    )

    users_db[user_id] = user

    # Create tokens
    access_token = jwt_manager.create_access_token(
        subject=user.username,
        payload={"user_id": user.id, "email": user.email}
    )

    refresh_token = jwt_manager.create_refresh_token(
        subject=user.username
    )

    return Token(
        access_token=access_token,
        refresh_token=refresh_token,
        expires_in=settings.ACCESS_TOKEN_EXPIRE_MINUTES * 60
    )

@app.post("/auth/login", response_model=Token)
@limiter.limit("5 per minute")
async def login(
    request: Request,
    form_data: OAuth2PasswordRequestForm = Depends()
):
    """Login endpoint with rate limiting and security controls"""
    client_ip = request.client.host

    # Check if IP is blocked
    if IPBlocker.is_ip_blocked(client_ip):
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="IP address temporarily blocked due to too many failed attempts"
        )

    # Find user
    user = next(
        (u for u in users_db.values() if u.username == form_data.username), 
        None
    )

    # Security: Use constant-time comparison
    valid_user = user is not None

    if valid_user:
        # Check if account is locked
        if user.locked_until and user.locked_until > datetime.utcnow():
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="Account temporarily locked"
            )

        # Verify password
        if SecurityUtils.verify_password(form_data.password, user.hashed_password):
            # Successful login
            user.failed_login_attempts = 0
            user.locked_until = None
            user.last_login = datetime.utcnow()

            # Create tokens
            access_token = jwt_manager.create_access_token(
                subject=user.username,
                payload={"user_id": user.id, "email": user.email}
            )

            refresh_token = jwt_manager.create_refresh_token(
                subject=user.username
            )

            return Token(
                access_token=access_token,
                refresh_token=refresh_token,
                expires_in=settings.ACCESS_TOKEN_EXPIRE_MINUTES * 60
            )
        else:
            # Failed login
            user.failed_login_attempts += 1

            if user.failed_login_attempts >= settings.MAX_LOGIN_ATTEMPTS:
                user.locked_until = datetime.utcnow() + timedelta(
                    minutes=settings.LOCKOUT_TIME_MINUTES
                )
                # Also block IP after multiple failures
                IPBlocker.block_ip(client_ip)

    # Simulate password verification for constant-time
    SecurityUtils.verify_password("dummy_password", SecurityUtils.hash_password("dummy"))

    raise HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Incorrect username or password"
    )

@app.post("/auth/refresh", response_model=Token)
async def refresh_token(
    request: RefreshTokenRequest
):
    """Refresh access token using refresh token"""
    try:
        # Verify refresh token
        payload = jwt_manager.verify_token(
            request.refresh_token, 
            token_type="refresh"
        )

        # Revoke the old refresh token (refresh token rotation)
        jwt_manager.revoke_token(request.refresh_token)

        # Create new tokens
        access_token = jwt_manager.create_access_token(
            subject=payload["sub"],
            payload={k: v for k, v in payload.items() if k not in ["exp", "iat", "type", "jti"]}
        )

        refresh_token = jwt_manager.create_refresh_token(
            subject=payload["sub"]
        )

        return Token(
            access_token=access_token,
            refresh_token=refresh_token,
            expires_in=settings.ACCESS_TOKEN_EXPIRE_MINUTES * 60
        )

    except HTTPException:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid refresh token"
        )

@app.post("/auth/logout")
async def logout(
    current_user: dict = Depends(get_current_active_user),
    request: Request = None
):
    """Logout endpoint - revoke tokens"""
    auth_header = request.headers.get("Authorization")
    if auth_header and auth_header.startswith("Bearer "):
        token = auth_header.split(" ")[1]
        jwt_manager.revoke_token(token)

    return {"message": "Successfully logged out"}

